// Tres camiones, un solo hilo: un planificador les va dando el turno de a uno.
function* camion(nombre, entregas) {
  for (let i = 1; i <= entregas; i++) {
    console.log(`${nombre}: entrega ${i} de ${entregas}`);
    yield; // cede el turno: «seguí vos»
  }
  console.log(`${nombre}: terminó`);
}

function correr(tareas) {
  const fila = [...tareas];
  while (fila.length > 0) {
    const t = fila.shift();
    const r = t.next();        // corre hasta el próximo yield
    if (!r.done) fila.push(t); // si falta trabajo, vuelve al final de la fila
  }
}

correr([camion("A", 3), camion("B", 2), camion("C", 3)]);

let stock = 10; // unidades en el depósito

function correr(tareas) {
  const fila = [...tareas];
  while (fila.length > 0) {
    const t = fila.shift();
    if (!t.next().done) fila.push(t);
  }
}

// Con un hueco: lee el stock, cede el turno, y recién después escribe.
function* despacharConHueco(nombre, cantidad) {
  const leido = stock;       // 1) leo
  yield;                     // 2) acá puede entrar otra tarea
  stock = leido - cantidad;  // 3) escribo con un dato que quedó viejo
  console.log(`${nombre} despachó ${cantidad}: stock ${stock}`);
}
correr([despacharConHueco("A", 3), despacharConHueco("B", 4)]);
console.log("con hueco, stock final:", stock, "(tendría que ser 3)\n");

// Sin hueco: leer y escribir en un solo turno.
stock = 10;
function* despacharSinHueco(nombre, cantidad) {
  stock = stock - cantidad;  // leer y escribir sin ceder el turno en el medio
  console.log(`${nombre} despachó ${cantidad}: stock ${stock}`);
  yield;
}
correr([despacharSinHueco("A", 3), despacharSinHueco("B", 4)]);
console.log("sin hueco, stock final:", stock);

// Un «actor» mínimo: el stock tiene un solo dueño y los demás le mandan mensajes.
function crearDeposito(stockInicial) {
  let stock = stockInicial;       // privado: nadie más lo toca
  const buzon = [];
  return {
    enviar(msg) { buzon.push(msg); },
    procesar() {
      while (buzon.length > 0) {
        const msg = buzon.shift(); // un mensaje por vez, en orden de llegada
        if (msg.tipo === "despachar") {
          stock -= msg.cantidad;
          console.log(`${msg.de} despachó ${msg.cantidad}: stock ${stock}`);
        }
      }
    },
  };
}

const deposito = crearDeposito(10);
deposito.enviar({ tipo: "despachar", de: "A", cantidad: 3 });
deposito.enviar({ tipo: "despachar", de: "B", cantidad: 4 });
deposito.procesar();

// Ley de Amdahl: aceleración = 1 / ((1 - p) + p / s)
// p = fracción que se puede paralelizar; s = cuántas veces más recursos.
const speedup = (p, s) => 1 / ((1 - p) + p / s);
const fracciones = [0.5, 0.9, 0.95, 0.99];
const recursos = [2, 4, 8, 16, 64, Infinity];

console.log("p \\ s    " + recursos.map(s => String(s).padStart(6)).join(" "));
for (const p of fracciones) {
  console.log(String(p).padEnd(8) + " " + recursos.map(s => speedup(p, s).toFixed(2).padStart(6)).join(" "));
}

