// envios.mjs: procesar envíos en secuencia o con worker_threads (node 22)
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";
import { fileURLToPath } from "node:url";

const PARADAS = 7;

function paradasDe(id) {            // las paradas salen del número de envío
  let s = (id * 2654435761) >>> 0;
  const sig = () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return (s >>> 8) % 10000 / 100; };
  const pts = [[50, 50]];           // el depósito
  for (let i = 0; i < PARADAS; i++) pts.push([sig(), sig()]);
  return pts;
}

function mejorRuta(id) {            // prueba todos los órdenes posibles
  const p = paradasDe(id), n = p.length;
  const d = p.map(a => p.map(b => Math.hypot(a[0] - b[0], a[1] - b[1])));
  const usado = new Array(n).fill(false);
  let mejor = Infinity;
  function visitar(actual, cuantas, largo) {
    if (cuantas === n) { const total = largo + d[actual][0]; if (total < mejor) mejor = total; return; }
    for (let j = 1; j < n; j++) {
      if (!usado[j]) { usado[j] = true; visitar(j, cuantas + 1, largo + d[actual][j]); usado[j] = false; }
    }
  }
  visitar(0, 1, 0);
  return mejor;
}

function procesar(desde, hasta) {   // suma de enteros: no depende del orden
  let suma = 0;
  for (let id = desde; id < hasta; id++) suma += Math.round(mejorRuta(id) * 1000);
  return suma;
}

if (isMainThread) {
  const TOTAL = Number(process.argv[2] ?? 10000), W = Number(process.argv[3] ?? 0);
  const t0 = performance.now();
  if (W === 0) {
    console.log(`secuencial: ${procesar(0, TOTAL)} en ${(performance.now() - t0).toFixed(0)} ms`);
  } else {
    const trozo = Math.ceil(TOTAL / W);
    const promesas = [];
    for (let w = 0; w < W; w++) {
      promesas.push(new Promise((ok, mal) => {
        const h = new Worker(fileURLToPath(import.meta.url), { workerData: { desde: w * trozo, hasta: Math.min(TOTAL, (w + 1) * trozo) } });
        h.once("message", ok); h.once("error", mal);
      }));
    }
    const sumas = await Promise.all(promesas);
    console.log(`${W} workers: ${sumas.reduce((a, b) => a + b, 0)} en ${(performance.now() - t0).toFixed(0)} ms`);
  }
} else {
  parentPort.postMessage(procesar(workerData.desde, workerData.hasta));  // el resultado vuelve como mensaje
}

// El mismo reparto en Go: una goroutine por trozo y un canal con los resultados.
trozo := (total + g - 1) / g
var wg sync.WaitGroup
resultados := make(chan int64, g)
for w := 0; w < g; w++ {
    wg.Add(1)
    go func(desde, hasta int) {
        defer wg.Done()
        resultados <- procesar(desde, hasta)
    }(w*trozo, min((w+1)*trozo, total))
}
wg.Wait()
close(resultados)
for r := range resultados {
    suma += r
}
